136	 */
137	@Data
138	@Builder
139	@AllArgsConstructor
140	@NoArgsConstructor
141	public class InstantOrderRequestDto {
142	
143	    @NotNull(message = "판매 입찰 ID는 필수입니다.")
144	    private Long saleBidId;                 // 판매 입찰 ID
145	
146	    @NotNull(message = "배송지 ID는 필수입니다.")
147	    private Long addressId;                 // 주소 ID
148	
149	    private boolean warehouseStorage;       // 창고 보관 여부
150	
151	    @NotNull(message = "결제 정보는 필수입니다.")
152	    private PaymentRequestDto paymentRequest; // 결제 정보
